// Header glyph hash. The icon is the gray mark near y=25, above the page body.
// c1 looked for a saturated green rule and c2 stopped at y=48 without a hash.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const REF = 'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c1-zone-open.png';
const OTHERS = [
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c2-zone-open.png',
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-c1-2154-open.png',
  'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/accept-j1-control-2154-open.png',
  'work/out/accept-k1-c1-zone-open.png',
  'work/out/accept-k1-c2-zone-open.png',
];

function readPng(file) {
  const data = readFileSync(file);
  const width = data.readUInt32BE(16);
  const height = data.readUInt32BE(20);
  const idat = [];
  for (let pos = 8; pos + 8 <= data.length;) {
    const length = data.readUInt32BE(pos);
    const kind = data.toString('latin1', pos + 4, pos + 8);
    if (kind === 'IDAT') idat.push(data.subarray(pos + 8, pos + 8 + length));
    pos += 12 + length;
    if (kind === 'IEND') break;
  }
  const raw = inflateSync(Buffer.concat(idat));
  const rows = [];
  const stride = width * 3;
  for (let y = 0; y < height; y++) {
    if (raw[(stride + 1) * y] !== 0) throw new Error('filter in ' + file);
    rows.push(raw.subarray((stride + 1) * y + 1, (stride + 1) * y + 1 + stride));
  }
  return { width, height, rows };
}

function lit(p) {
  return p[0] > 24 || p[1] > 24 || p[2] > 24;
}

function rowCount(img, y) {
  let n = 0;
  for (let x = 0; x < img.width; x++) {
    const i = x * 3;
    if (lit([img.rows[y][i], img.rows[y][i + 1], img.rows[y][i + 2]])) n += 1;
  }
  return n;
}

function headerBox(img) {
  const rows = [];
  for (let y = 0; y < 80 && y < img.height; y++) {
    const n = rowCount(img, y);
    if (n > img.width / 4) break;
    if (n > 0) rows.push(y);
  }
  if (!rows.length) return null;
  let x0 = img.width;
  let x1 = -1;
  let n = 0;
  const y0 = rows[0];
  const y1 = rows[rows.length - 1];
  for (let y = y0; y <= y1; y++) {
    for (let x = 0; x < img.width; x++) {
      const i = x * 3;
      if (!lit([img.rows[y][i], img.rows[y][i + 1], img.rows[y][i + 2]])) continue;
      n += 1;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
    }
  }
  return { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, pixels: n, rows };
}

function hashRect(img, rect) {
  const parts = [];
  for (let y = rect.y; y < rect.y + rect.h; y++) {
    parts.push(img.rows[y].subarray(rect.x * 3, (rect.x + rect.w) * 3));
  }
  return createHash('sha256').update(Buffer.concat(parts)).digest('hex');
}

function textsOf(id) {
  const out = [];
  for (const line of readFileSync('work/out/accept-k1.jsonl', 'utf8').split(/\n/)) {
    if (!line.includes('"id":"' + id + '"')) continue;
    const rec = JSON.parse(line);
    if (rec.id !== id || !out.length) {
      if (rec.id === id) {
        out.push({
          session: rec.session,
          title: rec.actual.title,
          helpText: rec.actual.helpText,
          texts: rec.actual.texts,
          highlight: rec.actual.highlight,
        });
      }
    }
  }
  return out;
}

const ref = readPng(REF);
const box = headerBox(ref);
if (!box || box.w > 80 || box.h > 40 || box.pixels < 8) {
  throw new Error('header box rejected ' + JSON.stringify(box));
}
const sha = hashRect(ref, box);
const files = [{ file: REF, hash: sha, match: true }];
for (const file of OTHERS) {
  const img = readPng(file);
  const hash = img.width === ref.width && img.height === ref.height ? hashRect(img, box) : null;
  files.push({ file, hash, match: hash === sha, width: img.width, height: img.height });
}
const doc = {
  reference: REF,
  width: ref.width,
  height: ref.height,
  rect: { x: box.x, y: box.y, w: box.w, h: box.h },
  pixels: box.pixels,
  rows: box.rows,
  sha256: sha,
  files,
  chooserTexts: {
    '2154-open': textsOf('2154-open'),
    'zone-open': textsOf('zone-open'),
  },
  note: 'SHA-256 of the chooser header glyph pixels. The help sentence is not an input.',
};
writeFileSync('work/out/header-ref-c3.json', JSON.stringify(doc, null, 2) + '\n');
const bad = files.filter((f) => !f.match);
console.log(JSON.stringify({
  rect: doc.rect,
  pixels: box.pixels,
  sha256: sha,
  bad: bad.map((f) => f.file),
  zoneTexts: doc.chooserTexts['zone-open'][0],
  rowTexts: doc.chooserTexts['2154-open'][0],
}, null, 2));
if (bad.length) process.exitCode = 1;
